  let y=await pdfHeader(doc,'COMPROBANTE DE PAGO A PROVEEDOR',['CHEMAS JC SPORT','Proveedor: '+(p.supplierName||'-'),'Fecha de pago: '+dateFmt(p.date),'Comprobante / referencia: '+(p.receiptRef||'-')]);
