/* ===================== ACTUALIZACIONES ===================== */
let swReg=null;
const appVersion=()=>{const m=/Versi[oó]n\s*([\d.]+)/.exec(document.querySelector('footer')?.textContent||'');return m?m[1]:'';};
function showUpdateBanner(){if($('#updBanner'))return;const d=document.createElement('div');d.id='updBanner';d.innerHTML='<span>Hay una versión nueva de la app.</span><button type="button" id="updNow">Actualizar ahora</button>';document.body.appendChild(d);$('#updNow').onclick=applyUpdate;}
async function applyUpdate(){try{if(window.caches){const ks=await caches.keys();await Promise.all(ks.map(k=>caches.delete(k)));}}catch(e){}location.reload();}
async function checkUpdate(manual){
  let found=false;
  try{if(swReg)await swReg.update();}catch(e){}
  try{const r=await fetch('./index.html?v='+Date.now(),{cache:'no-store'});if(r.ok){const m=/Versi[oó]n\s*([\d.]+)/.exec(await r.text());if(m&&m[1]!==appVersion())found=true;}else if(manual)return notify('No se pudo revisar. Verifica tu internet.');}catch(e){if(manual)return notify('No se pudo revisar. Verifica tu internet.');}
  if(found){showUpdateBanner();if(manual)notify('Hay una versión nueva. Toca «Actualizar ahora».');}else if(manual)notify('Ya tienes la última versión ('+appVersion()+').');}
function setupUpdates(){
  $('#salesSearch')?.addEventListener('input',renderSales);
  $('#checkUpdate')?.addEventListener('click',()=>checkUpdate(true));
  if(!('serviceWorker'in navigator&&location.protocol.startsWith('http')))return;
  const had=!!navigator.serviceWorker.controller;
  navigator.serviceWorker.register('./sw.js').then(r=>{swReg=r;}).catch(err=>console.warn('No se pudo registrar el modo offline',err));
  navigator.serviceWorker.addEventListener('controllerchange',()=>{if(had)showUpdateBanner();});
  setTimeout(()=>checkUpdate(false),4000);
  document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')checkUpdate(false);});
  setInterval(()=>checkUpdate(false),30*60*1000);}


/* ===================== SEGURIDAD COMPARTIDA (PIN en todos los dispositivos) ===================== */
const PRIV_KEY='chemas-privacy-pin2',CFG_ID='cfg-security';
const getPrivPin=()=>{try{return JSON.parse(localStorage.getItem(PRIV_KEY)||'null');}catch(e){return null;}};
async function pushSecurity(removedSync){const old=await get('suppliers',CFG_ID);await put('suppliers',{...old,id:CFG_ID,name:'⚙ Configuración de la app (no borrar)',mode:'contado',privacyPin:getPrivPin()||'',syncPin:getPin()||'',syncPinRemoved:!!removedSync,createdAt:(old&&old.createdAt)||Date.now(),updatedAt:Date.now()});}
async function setPrivPin(pin){const salt=uid();localStorage.setItem(PRIV_KEY,JSON.stringify({salt,hash:await pinHash(pin,salt)}));await pushSecurity();}
async function applySecurity(){try{
  const legacy=localStorage.getItem('chemas_privacy_pin');if(legacy&&!getPrivPin()){const salt=uid();localStorage.setItem(PRIV_KEY,JSON.stringify({salt,hash:await pinHash(legacy,salt)}));localStorage.removeItem('chemas_privacy_pin');}
  const rec=await get('suppliers',CFG_ID),lp=getPrivPin(),ls=getPin();
  if(!rec){if(lp||ls)await pushSecurity();return;}
  if(rec.privacyPin&&rec.privacyPin.hash&&(!lp||lp.hash!==rec.privacyPin.hash))localStorage.setItem(PRIV_KEY,JSON.stringify(rec.privacyPin));
  if(rec.syncPin&&rec.syncPin.hash){if(!ls||ls.hash!==rec.syncPin.hash){localStorage.setItem(PIN_KEY,JSON.stringify(rec.syncPin));if(typeof applySyncLock==='function')applySyncLock();}}
  else if(rec.syncPinRemoved&&ls){localStorage.removeItem(PIN_KEY);if(typeof applySyncLock==='function')applySyncLock();}
  else if(ls||(lp&&!(rec.privacyPin&&rec.privacyPin.hash)))await pushSecurity();
}catch(e){console.warn('security',e);}}

/* ===================== UNIFICAR A BRAYAN ===================== */
async function mergeBrayans(){try{const vs=(await all('suppliers')).filter(v=>norm(v.name).includes('brayan'));if(vs.length<2)return;const main=vs.find(v=>norm(v.name).includes('sevilla'))||vs[0];
  for(const v of vs){if(v.id===main.id)continue;for(const st of ['supplierPayments','supplierLots'])for(const r of await all(st))if(r.supplierId===v.id)await put(st,{...r,supplierId:main.id,supplierName:main.name,updatedAt:Date.now()});await del('suppliers',v.id);}
  if(main.mode==='contado')await put('suppliers',{...main,mode:'consignacion',updatedAt:Date.now()});}catch(e){console.warn('merge',e);}}

